import React, { useContext, useEffect } from 'react';
import AppBar from '@mui/material/AppBar';
import Box from '@mui/material/Box';
import Toolbar from '@mui/material/Toolbar';
import Typography from '@mui/material/Typography';
import { useNavigate } from 'react-router-dom';
import { MainContext } from '../context/MainContext';

export default function Navbar() {
  const { user, fetchUser } = useContext(MainContext);
  const navigate = useNavigate();

  useEffect(() => {
    fetchUser();
  }, [fetchUser]);


  return (
    <AppBar position="absolute" sx={{ top: 0, left: 0, right: 0, backgroundColor: 'transparent', boxShadow: 'none' }}>
      <Toolbar>
        <Box sx={{ flexGrow: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', height: '64px', position: 'relative' }}>
          <Box component="img"
            src={`${process.env.PUBLIC_URL + '/icones/lannobsgo.png'}`}
            alt="App Logo"
            sx={{ height: 60, cursor: 'pointer', position: 'absolute', top: '50%', transform: 'translateY(-50%)' }}
            onClick={() => navigate('/')}
          />
        </Box>
      </Toolbar>
    </AppBar>
  );
}
